+import { type AnyColumn, Column } from '~/column.ts';
+import { entityKind, is } from '~/entity.ts';
+import { isSQLWrapper, SQL, sql, type SQLWrapper } from '../sql.ts';
+
+type InferExpressionType<T> = T extends AnyColumn ? T['_']['data']
+	: T extends SQL<infer U> ? U
+	: T extends SQL.Aliased<infer U> ? U
+	: unknown;
+
+// ---------------------------------------------------------------------------
+// Frame boundaries
+// ---------------------------------------------------------------------------
+
+export type WindowFrameBoundaryKind =
+	| 'unbounded preceding'
+	| 'preceding'
+	| 'current row'
+	| 'following'
+	| 'unbounded following';
+
+export class WindowFrameBoundary {
+	static readonly [entityKind]: string = 'WindowFrameBoundary';
+
+	constructor(
+		readonly kind: WindowFrameBoundaryKind,
+		readonly offset?: number,
+	) {}
+
+	/** @internal Position of the boundary used to validate frame ordering. */
+	getPosition(): number {
+		switch (this.kind) {
+			case 'unbounded preceding': {
+				return Number.NEGATIVE_INFINITY;
+			}
+			case 'preceding': {
+				return -this.offset!;
+			}
+			case 'current row': {
+				return 0;
+			}
+			case 'following': {
+				return this.offset!;
+			}
+			case 'unbounded following': {
+				return Number.POSITIVE_INFINITY;
+			}
+		}
+	}
+
+	toString(): string {
+		return this.kind === 'preceding' || this.kind === 'following' ? `${this.offset} ${this.kind}` : this.kind;
+	}
+
+	getSQL(): SQL {
+		return sql.raw(this.toString());
+	}
+}
+
+/** `unbounded preceding` frame boundary. */
+export const unboundedPreceding = new WindowFrameBoundary('unbounded preceding');
+/** `current row` frame boundary. */
+export const currentRow = new WindowFrameBoundary('current row');
+/** `unbounded following` frame boundary. */
+export const unboundedFollowing = new WindowFrameBoundary('unbounded following');
+
+function assertFrameOffset(helper: string, offset: number): void {
+	if (typeof offset !== 'number' || !Number.isInteger(offset) || offset < 0) {
+		throw new Error(`${helper}() expects a non-negative integer, received: ${String(offset)}`);
+	}
+}
+
+/** `<n> preceding` frame boundary. */
+export function preceding(offset: number): WindowFrameBoundary {
+	assertFrameOffset('preceding', offset);
+	return new WindowFrameBoundary('preceding', offset);
+}
+
+/** `<n> following` frame boundary. */
+export function following(offset: number): WindowFrameBoundary {
+	assertFrameOffset('following', offset);
+	return new WindowFrameBoundary('following', offset);
+}
+
+// ---------------------------------------------------------------------------
+// Frames
+// ---------------------------------------------------------------------------
+
+export interface WindowFrameSpec {
+	from: WindowFrameBoundary;
+	to?: WindowFrameBoundary;
+}
+
+export type WindowFrameMode = 'rows' | 'range';
+
+export class WindowFrame implements SQLWrapper {
+	static readonly [entityKind]: string = 'WindowFrame';
+
+	constructor(
+		readonly mode: WindowFrameMode,
+		readonly from: WindowFrameBoundary,
+		readonly to?: WindowFrameBoundary,
+	) {}
+
+	getSQL(): SQL {
+		if (this.to === undefined) {
+			return sql`${sql.raw(this.mode)} ${this.from.getSQL()}`;
+		}
+		return sql`${sql.raw(this.mode)} between ${this.from.getSQL()} and ${this.to.getSQL()}`;
+	}
+}
+
+function buildFrame(mode: WindowFrameMode, spec: WindowFrameSpec): WindowFrame {
+	if (!spec || !is(spec.from, WindowFrameBoundary)) {
+		t
